package main

import (
	"fmt"
	"strings"
)

const bashCompletion = `# wire bash completions to dstask completion engine. Some of the workarounds for
# idiosyncrasies around separation with colons taken from /etc/bash_completion

_dstask() {
    # reconstruct COMP_WORDS to re-join separations caused by colon (which is a default separator)
    # yes, this method ends up splitting by spaces, but that's not a problem for the dstask parser
    # see http://tiswww.case.edu/php/chet/bash/FAQ
    original_args=( $(echo "${COMP_WORDS[@]}" | sed 's/ : /:/g' | sed 's/ :$/:/g') )

    # hand to dstask as canonical args
    COMPREPLY=( $(dstask _completions "${original_args[@]}") )

    # convert dstask's suggestions to remove prefix before colon so complete can understand it
    local last_arg="${original_args[-1]}"
    local colon_word=${last_arg%"${last_arg##*:}"}
    local i=${#COMPREPLY[*]}
    while [[ $((--i)) -ge 0 ]]; do
        COMPREPLY[$i]=${COMPREPLY[$i]#"$colon_word"}
    done
}

complete -F _dstask dstask
complete -F _dstask task
#complete -F _dstask n
#complete -F _dstask t
`

const zshCompletion = `#compdef dstask
#autoload


_dstask() {
    compadd -- $(dstask _completions "${words[@]}")
}

compdef _dstask dstask
`

const fishCompletion = `#!/usr/bin/env fish

complete -f -c dstask -a (echo (dstask _completions) | string collect)
#complete -f -c task -a (echo (task _completions) | string collect)
#complete -f -c t -a (echo (t _completions) | string collect)

`

// allCommands lists the base command completions used in _completions output.
// The order matches the original binary.
var completionCommands = []string{
	"next",
	"add",
	"rm",
	"remove",
	"template",
	"log",
	"start",
	"note",
	"notes",
	"stop",
	"done",
	"resolve",
	"context",
	"modify",
	"edit",
	"undo",
	"sync",
	"open",
	"git",
	"show-next",
	"show-projects",
	"show-tags",
	"show-active",
	"show-paused",
	"show-open",
	"show-resolved",
	"show-templates",
	"show-unorganised",
	"bash-completion",
	"fish-completion",
	"zsh-completion",
	"help",
	"version",
}

// printCompletions implements the `_completions` command.
func printCompletions(args []string) {
	// args is the full command line including the program name, e.g.:
	//   dstask _completions dstask add +f
	// After strip of "_completions", args is dstask, <typed args...>
	// The bash wrapper passes COMP_WORDS which ends with current prefix (may be "").

	// Determine the prefix being completed (last word), and the "prior" args.
	var prefix string
	var prior []string
	if len(args) == 0 {
		prefix = ""
	} else {
		prefix = args[len(args)-1]
		prior = args[:len(args)-1]
	}
	_ = prior

	repo, _ := loadRepo()
	tasks := []*Task{}
	if repo != nil {
		tasks, _ = repo.loadAllTasks()
	}

	tagSet := map[string]bool{}
	projSet := map[string]bool{}
	for _, t := range tasks {
		if t.Status == "resolved" {
			continue
		}
		for _, tag := range t.Tags {
			tagSet[tag] = true
		}
		if t.Project != "" {
			projSet[t.Project] = true
		}
	}

	out := []string{}

	// If prefix starts with + or -, tag completion
	switch {
	case strings.HasPrefix(prefix, "+"):
		for tag := range tagSet {
			out = append(out, "+"+tag)
		}
	case strings.HasPrefix(prefix, "-"):
		for tag := range tagSet {
			out = append(out, "-"+tag)
		}
	case strings.HasPrefix(prefix, "project:"):
		for p := range projSet {
			out = append(out, "project:"+p)
		}
	case strings.HasPrefix(prefix, "-project:"):
		for p := range projSet {
			out = append(out, "-project:"+p)
		}
	default:
		out = append(out, completionCommands...)
		out = append(out, "P0", "P1", "P2", "P3")
		for tag := range tagSet {
			out = append(out, "+"+tag)
			out = append(out, "-"+tag)
		}
		for p := range projSet {
			out = append(out, "project:"+p)
		}
	}

	// Filter to those matching prefix
	filtered := []string{}
	for _, o := range out {
		if strings.HasPrefix(o, prefix) {
			filtered = append(filtered, o)
		}
	}

	for _, o := range filtered {
		fmt.Println(o)
	}
}
EOF
echo "wrote completion.go"

