package main

import (
	"crypto/rand"
	"fmt"
	"regexp"
	"sort"
	"strings"
	"time"
)

// Task represents a single task stored in the repository.
type Task struct {
	UUID         string
	Status       string
	ID           int
	Summary      string
	Notes        string
	Tags         []string
	Project      string
	Priority     string
	DelegatedTo  string
	Subtasks     []Subtask
	Dependencies []string
	Created      time.Time
	Resolved     time.Time
	Due          time.Time
}

// Subtask is a simple checklist item (currently unused by the CLI, but part of the on-disk schema).
type Subtask struct {
	Summary  string
	Resolved bool
}

const (
	StatusPending   = "pending"
	StatusActive    = "active"
	StatusPaused    = "paused"
	StatusResolved  = "resolved"
	StatusDeferred  = "deferred"
	StatusDelegated = "delegated"
	StatusRecurring = "recurring"
	StatusTemplate  = "template"
)

var statusDirs = []string{
	StatusPending,
	StatusActive,
	StatusPaused,
	StatusResolved,
	StatusDeferred,
	StatusDelegated,
	StatusRecurring,
	StatusTemplate,
}

var nonResolvedStatuses = []string{
	StatusPending,
	StatusActive,
	StatusPaused,
	StatusDeferred,
	StatusDelegated,
	StatusRecurring,
}

const (
	PriorityCritical = "P0"
	PriorityHigh     = "P1"
	PriorityNormal   = "P2"
	PriorityLow      = "P3"
)

func newUUID() string {
	b := make([]byte, 16)
	rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40 // Version 4
	b[8] = (b[8] & 0x3f) | 0x80 // Variant
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
		b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

// Query represents parsed filter/command-line arguments.
type Query struct {
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Priority      string
	Template      int
	HasTemplate   bool
	Text          []string
	IgnoreContext bool
	Due           string
}

var (
	rePriority = regexp.MustCompile(`^P[0-3]$`)
	reTag      = regexp.MustCompile(`^\+([A-Za-z0-9_\-\.]+)$`)
	reAntiTag  = regexp.MustCompile(`^-([A-Za-z0-9_\-\.]+)$`)
	reProject  = regexp.MustCompile(`^project:([A-Za-z0-9_\-\.]*)$`)
	reAntiProj = regexp.MustCompile(`^-project:([A-Za-z0-9_\-\.]*)$`)
	reTemplate = regexp.MustCompile(`^template:(\d+)$`)
	reDue      = regexp.MustCompile(`^due:(\S*)$`)
	reID       = regexp.MustCompile(`^\d+$`)
)

func parseQuery(args []string) (Query, string) {
	// Separate the command from the arguments. Returns the command and the remaining args.
	// Task IDs may appear at the start. The command is the first non-numeric arg.
	// Actually, we split command externally. parseQuery just parses task-expression args.
	var q Query
	var text []string
	for _, a := range args {
		if a == "--" {
			q.IgnoreContext = true
			continue
		}
		switch {
		case reTag.MatchString(a):
			q.Tags = append(q.Tags, a[1:])
		case reAntiTag.MatchString(a):
