package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

// writeTaskYAML serializes a task to the YAML format used on-disk.
func writeTaskYAML(t *Task) string {
	var b strings.Builder
	fmt.Fprintf(&b, "summary: %s\n", yamlScalar(t.Summary))
	fmt.Fprintf(&b, "notes: %s\n", yamlNotes(t.Notes))
	b.WriteString("tags:")
	if len(t.Tags) == 0 {
		b.WriteString(" []\n")
	} else {
		b.WriteString("\n")
		for _, tag := range t.Tags {
			fmt.Fprintf(&b, "- %s\n", yamlScalar(tag))
		}
	}
	fmt.Fprintf(&b, "project: %s\n", yamlScalar(t.Project))
	fmt.Fprintf(&b, "priority: %s\n", t.Priority)
	fmt.Fprintf(&b, "delegatedto: %s\n", yamlScalar(t.DelegatedTo))
	b.WriteString("subtasks: []\n")
	b.WriteString("dependencies: []\n")
	fmt.Fprintf(&b, "created: %s\n", yamlTime(t.Created))
	fmt.Fprintf(&b, "resolved: %s\n", yamlTime(t.Resolved))
	fmt.Fprintf(&b, "due: %s\n", yamlTime(t.Due))
	return b.String()
}

func yamlScalar(s string) string {
	if s == "" {
		return `""`
	}
	if strings.ContainsAny(s, "\n\"\t") || needsQuoting(s) {
		return strconv.Quote(s)
	}
	return s
}

func needsQuoting(s string) bool {
	// Conservative: plain-style must not start with reserved indicators.
	if len(s) == 0 {
		return true
	}
	first := s[0]
	switch first {
	case ' ', '\t', '#', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`', '{', '}', '[', ']', ',', '?', ':', '-':
		return true
	}
	return false
}

func yamlNotes(s string) string {
	if s == "" {
		return `""`
	}
	// Multi-line block scalar: use |2- with exactly one leading blank line for non-empty notes.
	// Existing binary outputs `|2-` plus each line indented by two spaces; the content begins
	// with a blank line and ends without trailing newline (strip chomping).
	lines := strings.Split(s, "\n")
	var b strings.Builder
	b.WriteString("|2-")
	for _, l := range lines {
		b.WriteString("\n  ")
		b.WriteString(l)
	}
	return b.String()
}

func yamlTime(t time.Time) string {
	if t.IsZero() {
		return "0001-01-01T00:00:00Z"
	}
	return t.UTC().Format(time.RFC3339Nano)
}

// parseTaskYAML parses the limited YAML subset we write ourselves back into a Task.
func parseTaskYAML(data []byte) (*Task, error) {
	t := &Task{}
	lines := strings.Split(string(data), "\n")
	i := 0
	for i < len(lines) {
		line := lines[i]
		if line == "" {
			i++
			continue
		}
		if strings.HasPrefix(line, "- ") {
			i++
			continue
		}
		idx := strings.Index(line, ":")
		if idx < 0 {
			i++
			continue
		}
		key := strings.TrimSpace(line[:idx])
		rest := strings.TrimSpace(line[idx+1:])
		switch key {
		case "summary":
			t.Summary = parseYAMLScalar(rest)
		case "notes":
			if strings.HasPrefix(rest, "|") {
				// Block scalar
				indent := 2
				if m := blockIndent(rest); m > 0 {
					indent = m
				}
				chomp := ""
				if strings.HasSuffix(rest, "-") {
					chomp = "strip"
				}
				_ = chomp
				i++
				var sb strings.Builder
				first := true
				for i < len(lines) {
					l := lines[i]
					if l == "" {
						if !first {
							sb.WriteString("\n")
						}
						first = false
						i++
						continue
