package main

import (
	"bytes"
	"encoding/gob"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"time"
)

// Repo represents the dstask git-backed repository on disk.
type Repo struct {
	Path string
}

func repoPath() string {
	if p := os.Getenv("DSTASK_GIT_REPO"); p != "" {
		return p
	}
	home, err := os.UserHomeDir()
	if err != nil {
		home = os.Getenv("HOME")
	}
	return filepath.Join(home, ".dstask")
}

// loadRepo returns a *Repo if the directory exists and is a git repository.
// If the directory does not exist, it will be created and initialised as a git repo.
// If it exists but is not a git repo, returns an error.
func loadRepo() (*Repo, error) {
	p := repoPath()
	r := &Repo{Path: p}

	info, err := os.Stat(p)
	if os.IsNotExist(err) {
		// Create and git init
		if err := os.MkdirAll(p, 0755); err != nil {
			return nil, fmt.Errorf("Failed to create repository directory %s: %w", p, err)
		}
		if err := r.git("init"); err != nil {
			return nil, err
		}
		fmt.Fprintln(os.Stdout)
		fmt.Fprintln(os.Stdout, "Add a remote repository with:")
		fmt.Fprintln(os.Stdout)
		fmt.Fprintln(os.Stdout, "\tdstask git remote add origin <repo>")
		fmt.Fprintln(os.Stdout)
	} else if err != nil {
		return nil, err
	} else if !info.IsDir() {
		return nil, fmt.Errorf("not a directory: %s", p)
	}

	for _, d := range statusDirs {
		full := filepath.Join(p, d)
		if err := os.Mkdir(full, 0700); err != nil && !os.IsExist(err) {
			return nil, fmt.Errorf("Failed to create directory in git repository")
		}
	}
	return r, nil
}

// git runs a git command silently and returns error if any.
func (r *Repo) git(args ...string) error {
	cmd := exec.Command("git", append([]string{"-C", r.Path}, args...)...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

// gitOutput runs a git command and returns its combined output.
func (r *Repo) gitOutput(args ...string) ([]byte, error) {
	cmd := exec.Command("git", append([]string{"-C", r.Path}, args...)...)
	return cmd.CombinedOutput()
}

// gitCommit creates a commit with the given message, optionally adding the given paths.
func (r *Repo) gitCommit(msg string) error {
	if err := r.git("add", "-A"); err != nil {
		return err
	}
	out, err := r.gitOutput("commit", "-m", msg)
