func loadRepo() (*Repo, error) {
	p := repoPath()
	r := &Repo{Path: p}

	info, err := os.Stat(p)
	if os.IsNotExist(err) {
		// Create and git init
		if err := os.MkdirAll(p, 0755); err != nil {
			return nil, fmt.Errorf("Failed to create repository directory %s: %w", p, err)
		}
