// loadAllTasks reads all task YAML files in the repository.
func (r *Repo) loadAllTasks() ([]*Task, error) {
	ids := r.loadIDs()
	var tasks []*Task
	for _, status := range statusDirs {
		dir := filepath.Join(r.Path, status)
		entries, err := os.ReadDir(dir)
		if err != nil {
			continue
		}
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			name := e.Name()
			if filepath.Ext(name) != ".yml" {
				continue
			}
			full := filepath.Join(dir, name)
			data, err := os.ReadFile(full)
			if err != nil {
				continue
			}
			task, err := parseTaskYAML(data)
			if err != nil {
				continue
			}
			task.UUID = name[:len(name)-4]
			task.Status = status
			// find ID
			for id, uuid := range ids {
				if uuid == task.UUID {
					task.ID = id
