package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

func run(argv []string) error {
	// Extract command
	cmd, rest := splitCommand(argv)
	canonical := canonCmd(cmd)

	// Commands that don't touch repo
	switch canonical {
	case "help":
		if len(rest) > 0 {
			printHelp(canonCmd(rest[0]))
		} else {
			printHelp("")
		}
		return nil
	case "version":
		fmt.Println("Version: Unknown")
		fmt.Println("Git commit: Unknown")
		fmt.Println("Build date: Unknown")
		return nil
	case "bash-completion":
		fmt.Print(bashCompletion)
		return nil
	case "zsh-completion":
		fmt.Print(zshCompletion)
		return nil
	case "fish-completion":
		fmt.Print(fishCompletion)
		return nil
	case "_completions":
		printCompletions(rest)
		return nil
	}

	// Commands that need the repo
	repo, err := loadRepo()
	if err != nil {
		return err
	}

	ctxQuery, ctxSource := repo.loadContextQuery()
	q, _ := parseQuery(rest)

	applyContext := !q.IgnoreContext && canonical != "context"
	// Apply context to q for queries/new tasks
	effective := q
	if applyContext {
		// tags: union without duplicates, preserving order
		effective.Tags = mergeUnique(q.Tags, ctxQuery.Tags)
		effective.AntiTags = mergeUnique(q.AntiTags, ctxQuery.AntiTags)
		if effective.Project == "" {
			effective.Project = ctxQuery.Project
		}
		effective.AntiProjects = mergeUnique(q.AntiProjects, ctxQuery.AntiProjects)
		if effective.Priority == "" {
			effective.Priority = ctxQuery.Priority
		}
	}

	// Emit context hint for commands that apply context and when context is non-empty.
	if applyContext && hasContext(ctxQuery) && isContextualModifyingCmd(canonical) {
		suffix := ""
		if ctxSource == "DSTASK_CONTEXT" {
			suffix = " (set by DSTASK_CONTEXT)"
		}
		fmt.Fprintf(os.Stdout, "\033[33mActive context%s: %s\033[0m\n", suffix, formatContext(ctxQuery))
	}

	switch canonical {
	case "", "next":
		return listOpen(repo, effective, false)
	case "show-open":
		return listOpen(repo, effective, true)
	case "show-resolved":
		return listResolved(repo, effective)
	case "show-active":
		return listStatus(repo, effective, StatusActive)
	case "show-paused":
		return listStatus(repo, effective, StatusPaused)
	case "show-templates":
		return listStatus(repo, effective, StatusTemplate)
	case "show-unorganised":
		return listUnorganised(repo)
	case "show-tags":
		return listTags(repo, effective)
	case "show-projects":
		return listProjects(repo, effective)
	case "add":
		return cmdAdd(repo, effective, StatusPending)
	case "log":
		return cmdAdd(repo, effective, StatusResolved)
	case "template":
		return cmdAdd(repo, effective, StatusTemplate)
	case "start":
		return cmdChangeStatus(repo, effective, StatusActive, "Started")
	case "stop":
		return cmdStop(repo, effective)
	case "done":
		return cmdDone(repo, effective)
	case "remove":
		return cmdRemove(repo, effective)
	case "modify":
		return cmdModify(repo, effective, q)
	case "context":
		return cmdContext(repo, rest)
	case "edit":
		return cmdEdit(repo, effective)
	case "note":
		return cmdNote(repo, effective)
	case "open":
		return cmdOpen(repo, effective)
	case "undo":
		return cmdUndo(repo, rest)
	case "sync":
		return cmdSync(repo)
	case "git":
		return cmdGit(repo, rest)
	}

	// Unknown/empty command with args: default to listing open
	return listOpen(repo, effective, false)
}

func isContextualModifyingCmd(cmd string) bool {
	switch cmd {
	case "add", "log", "template", "start":
		return true
	}
	return false
}

func hasContext(q Query) bool {
	return len(q.Tags) > 0 || len(q.AntiTags) > 0 || q.Project != "" || len(q.AntiProjects) > 0 || q.Priority != ""
}

func mergeUnique(a, b []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, v := range append(a, b...) {
		if !seen[v] {
			seen[v] = true
			out = append(out, v)
		}
	}
	return out
}

func matchQuery(t *Task, q Query) bool {
	// Tags
	for _, tag := range q.Tags {
		found := false
		for _, tt := range t.Tags {
			if tt == tag {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, tag := range q.AntiTags {
		for _, tt := range t.Tags {
			if tt == tag {
				return false
			}
		}
	}
	if q.Project != "" && t.Project != q.Project {
		return false
	}
	for _, p := range q.AntiProjects {
		if t.Project == p {
			return false
		}
	}
	if q.Priority != "" && t.Priority != q.Priority {
		return false
	}
	// text substring search
	if len(q.Text) > 0 {
		text := strings.ToLower(t.Summary + " " + t.Notes)
		for _, w := range q.Text {
			if !strings.Contains(text, strings.ToLower(w)) {
				return false
			}
		}
	}
	return true
}

func filterByIDs(tasks []*Task, ids []int) []*Task {
	if len(ids) == 0 {
		return tasks
	}
	m := map[int]bool{}
	for _, id := range ids {
		m[id] = true
	}
	var out []*Task
	for _, t := range tasks {
		if m[t.ID] {
			out = append(out, t)
		}
	}
	return out
}

func listOpen(repo *Repo, q Query, all bool) error {
	tasks, err := repo.loadAllTasks()
	if err != nil {
		return err
	}
	var filtered []*Task
	for _, t := range tasks {
		if t.Status == StatusResolved || t.Status == StatusTemplate {
			continue
		}
		if !matchQuery(t, q) {
			continue
		}
		if len(q.IDs) > 0 {
			ok := false
			for _, id := range q.IDs {
				if t.ID == id {
					ok = true
					break
				}
			}
			if !ok {
				continue
			}
		}
		filtered = append(filtered, t)
	}
	sortTasks(filtered)
	emitTaskJSON(filtered)
	return nil
}

func listResolved(repo *Repo, q Query) error {
	tasks, err := repo.loadAllTasks()
	if err != nil {
		return err
	}
	var filtered []*Task
	for _, t := range tasks {
		if t.Status != StatusResolved {
			continue
		}
		if !matchQuery(t, q) {
			continue
		}
		filtered = append(filtered, t)
	}
	// Most recently resolved last? The original prints in a specific order: by resolution date
	sort.SliceStable(filtered, func(i, j int) bool {
		return filtered[i].Resolved.Before(filtered[j].Resolved)
