func listProjects(repo *Repo, q Query) error {
	tasks, err := repo.loadAllTasks()
	if err != nil {
		return err
	}
	grouped := map[string][]*Task{}
	for _, t := range tasks {
		if t.Project == "" {
			continue
		}
		grouped[t.Project] = append(grouped[t.Project], t)
	}
	var names []string
	for n := range grouped {
		names = append(names, n)
	}
	sort.Strings(names)
	var out []ProjectInfo
	for _, n := range names {
		ts := grouped[n]
		info := ProjectInfo{Name: n, Priority: "P3"}
		var oldestCreated, latestResolved time.Time
		for _, t := range ts {
			info.TaskCount++
			if t.Status == StatusResolved {
				info.ResolvedCount++
			}
			if t.Status == StatusActive {
				info.Active = true
			}
			if oldestCreated.IsZero() || t.Created.Before(oldestCreated) {
				oldestCreated = t.Created
			}
			if t.Resolved.After(latestResolved) {
				latestResolved = t.Resolved
			}
			// highest priority among tasks
			if priorityRank(t.Priority) < priorityRank(info.Priority) {
				info.Priority = t.Priority
			}
		}
		info.Created = oldestCreated
		info.Resolved = latestResolved
		out = append(out, info)
	}
	emitJSON(out)
	return nil
}

// Task output JSON item (shape matches binary).
type taskJSON struct {
	UUID     string    `json:"uuid"`
	Status   string    `json:"status"`
	ID       int       `json:"id"`
	Summary  string    `json:"summary"`
	Notes    string    `json:"notes"`
	Tags     []string  `json:"tags"`
	Project  string    `json:"project"`
	Priority string    `json:"priority"`
	Created  time.Time `json:"created"`
	Resolved time.Time `json:"resolved"`
	Due      time.Time `json:"due"`
}

func emitTaskJSON(tasks []*Task) {
	arr := []taskJSON{}
	for _, t := range tasks {
		tags := t.Tags
		if tags == nil {
			tags = []string{}
		}
		arr = append(arr, taskJSON{
			UUID:     t.UUID,
			Status:   t.Status,
			ID:       t.ID,
			Summary:  t.Summary,
			Notes:    t.Notes,
			Tags:     tags,
			Project:  t.Project,
			Priority: t.Priority,
			Created:  t.Created,
			Resolved: t.Resolved,
			Due:      t.Due,
		})
	}
	emitJSON(arr)
}

func emitJSON(v interface{}) {
	// The binary outputs the nano-second RFC3339 timestamps. encoding/json uses that format already.
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	out, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return
	}
	// Match format of the original: it emits without trailing newline.
	os.Stdout.Write(out)
	_ = enc
}

func cmdAdd(repo *Repo, q Query, status string) error {
	// Create task from query
	if len(q.Text) == 0 && !q.HasTemplate && status != StatusTemplate {
		return fmt.Errorf("nothing to add")
	}
	t := &Task{
		UUID:     newUUID(),
		Status:   status,
		Summary:  strings.Join(q.Text, " "),
		Tags:     tagSort(q.Tags),
		Project:  q.Project,
		Priority: q.Priority,
		Created:  time.Now().UTC(),
	}
	if t.Priority == "" {
		t.Priority = PriorityNormal
	}
	if status == StatusResolved {
		t.Resolved = t.Created
	}
	if q.Due != "" {
		if d, err := parseDate(q.Due); err == nil {
			t.Due = d
		}
	}
	if q.HasTemplate {
		// Copy an existing template's fields
		tasks, _ := repo.loadAllTasks()
		for _, other := range tasks {
			if other.Status == StatusTemplate && other.ID == q.Template {
				if t.Summary == "" {
					t.Summary = other.Summary
				}
				if t.Project == "" {
					t.Project = other.Project
				}
				if len(q.Tags) == 0 {
					t.Tags = other.Tags
				}
				if q.Priority == "" {
					t.Priority = other.Priority
				}
				t.Notes = other.Notes
				break
			}
		}
	}
	if err := repo.assignID(t); err != nil {
		return err
	}
	if err := repo.saveTask(t); err != nil {
		return err
	}
	prefix := "Added"
	if status == StatusResolved {
		prefix = "Resolved"
	}
	if status == StatusTemplate {
		prefix = "Added"
	}
	fmt.Println()
	fmt.Printf("%s %d: %s\n", prefix, t.ID, t.Summary)
	return repo.gitCommit(fmt.Sprintf("%s %d: %s", prefix, t.ID, t.Summary))
}

func parseDate(s string) (time.Time, error) {
	layouts := []string{"2006-01-02", "2006-01-02T15:04:05Z", time.RFC3339}
	for _, l := range layouts {
		if t, err := time.Parse(l, s); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("could not parse date %q", s)
}

