func isContextualModifyingCmd(cmd string) bool {
	switch cmd {
	case "add", "log", "template", "start":
		return true
	}
	return false
}

func hasContext(q Query) bool {
	return len(q.Tags) > 0 || len(q.AntiTags) > 0 || q.Project != "" || len(q.AntiProjects) > 0 || q.Priority != ""
}

func mergeUnique(a, b []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, v := range append(a, b...) {
		if !seen[v] {
			seen[v] = true
			out = append(out, v)
		}
	}
	return out
}

func matchQuery(t *Task, q Query) bool {
	// Tags
	for _, tag := range q.Tags {
		found := false
		for _, tt := range t.Tags {
			if tt == tag {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, tag := range q.AntiTags {
		for _, tt := range t.Tags {
			if tt == tag {
				return false
			}
		}
	}
	if q.Project != "" && t.Project != q.Project {
		return false
	}
	for _, p := range q.AntiProjects {
		if t.Project == p {
			return false
		}
	}
	if q.Priority != "" && t.Priority != q.Priority {
		return false
	}
	// text substring search
	if len(q.Text) > 0 {
		text := strings.ToLower(t.Summary + " " + t.Notes)
		for _, w := range q.Text {
			if !strings.Contains(text, strings.ToLower(w)) {
				return false
			}
		}
	}
	return true
}

func filterByIDs(tasks []*Task, ids []int) []*Task {
	if len(ids) == 0 {
		return tasks
	}
	m := map[int]bool{}
	for _, id := range ids {
		m[id] = true
	}
	var out []*Task
	for _, t := range tasks {
		if m[t.ID] {
			out = append(out, t)
		}
	}
	return out
}

