		return err
	}
	var filtered []*Task
	for _, t := range tasks {
		if t.Status == StatusResolved || t.Status == StatusTemplate {
			continue
		}
		if !matchQuery(t, q) {
			continue
		}
		if len(q.IDs) > 0 {
			ok := false
			for _, id := range q.IDs {
				if t.ID == id {
					ok = true
					break
				}
			}
			if !ok {
				continue
			}
		}
		filtered = append(filtered, t)
	}
	sortTasks(filtered)
	emitTaskJSON(filtered)
	return nil
}

func listResolved(repo *Repo, q Query) error {
	tasks, err := repo.loadAllTasks()
	if err != nil {
		return err
	}
	var filtered []*Task
	for _, t := range tasks {
		if t.Status != StatusResolved {
			continue
		}
		if !matchQuery(t, q) {
			continue
		}
		filtered = append(filtered, t)
	}
	// Most recently resolved last? The original prints in a specific order: by resolution date
	sort.SliceStable(filtered, func(i, j int) bool {
		return filtered[i].Resolved.Before(filtered[j].Resolved)
	})
	if len(filtered) > 1000 {
		filtered = filtered[len(filtered)-1000:]
	}
	emitTaskJSON(filtered)
	return nil
}

