func cmdRemove(repo *Repo, q Query) error {
	tasks, err := repo.loadAllTasks()
	if err != nil {
		return err
	}
	targets := filterByIDs(tasks, q.IDs)
	if len(targets) == 0 {
		if len(q.IDs) > 0 {
			return fmt.Errorf("no open task with ID %d exists", q.IDs[0])
		}
		return nil
	}
	for _, t := range targets {
		fmt.Printf("%d: %s\n", t.ID, t.Summary)
	}
	// Confirm if stdin is a TTY
	if isTerminal(os.Stdin.Fd()) {
		fmt.Printf("\nThe above %d task(s) will be deleted without checking subtasks. Continue? [y/n] ", len(targets))
		var resp string
		fmt.Scanln(&resp)
		if !strings.HasPrefix(strings.ToLower(resp), "y") {
			fmt.Println("\033[31mAborted.\033[0m")
			return nil
		}
	}
	for _, t := range targets {
		if err := repo.deleteTask(t.UUID); err != nil {
			return err
		}
		repo.releaseID(t.UUID)
		fmt.Println()
		fmt.Printf("Removed: %d: %s\n", t.ID, t.Summary)
		if err := repo.gitCommit(fmt.Sprintf("Removed: %d: %s", t.ID, t.Summary)); err != nil {
			return err
		}
