func cmdModify(repo *Repo, eff, raw Query) error {
	tasks, err := repo.loadAllTasks()
	if err != nil {
		return err
	}
	targets := filterByIDs(tasks, eff.IDs)
	if len(targets) == 0 {
		return fmt.Errorf("no open task with ID %d exists", func() int {
			if len(eff.IDs) > 0 {
				return eff.IDs[0]
			}
			return 0
		}())
	}
	for _, t := range targets {
		// Add tags
		for _, tag := range raw.Tags {
			t.Tags = mergeUnique(t.Tags, []string{tag})
		}
		// Remove tags
		if len(raw.AntiTags) > 0 {
			var keep []string
			for _, tag := range t.Tags {
				drop := false
				for _, bad := range raw.AntiTags {
					if tag == bad {
						drop = true
					}
				}
				if !drop {
					keep = append(keep, tag)
				}
			}
			t.Tags = keep
		}
		if raw.Project != "" {
			t.Project = raw.Project
		}
		for _, p := range raw.AntiProjects {
			if t.Project == p {
				t.Project = ""
			}
		}
		if raw.Priority != "" {
			t.Priority = raw.Priority
		}
		if err := repo.saveTask(t); err != nil {
			return err
		}
		fmt.Println()
		fmt.Printf("Modified %d: %s\n", t.ID, t.Summary)
		if err := repo.gitCommit(fmt.Sprintf("Modified %d: %s", t.ID, t.Summary)); err != nil {
			return err
		}
	}
	return nil
}

