// writeTaskYAML serializes a task to the YAML format used on-disk.
func writeTaskYAML(t *Task) string {
	var b strings.Builder
	fmt.Fprintf(&b, "summary: %s\n", yamlScalar(t.Summary))
	b.WriteString("notes: ")
	b.WriteString(yamlNotes(t.Notes))
	b.WriteString("\n")
	b.WriteString("tags:")
	if len(t.Tags) == 0 {
		b.WriteString(" []\n")
	} else {
		b.WriteString("\n")
		for _, tag := range t.Tags {
			fmt.Fprintf(&b, "- %s\n", yamlScalar(tag))
		}
	}
	fmt.Fprintf(&b, "project: %s\n", yamlScalar(t.Project))
	fmt.Fprintf(&b, "priority: %s\n", t.Priority)
	fmt.Fprintf(&b, "delegatedto: %s\n", yamlScalar(t.DelegatedTo))
	b.WriteString("subtasks: []\n")
	b.WriteString("dependencies: []\n")
	fmt.Fprintf(&b, "created: %s\n", yamlTime(t.Created))
	fmt.Fprintf(&b, "resolved: %s\n", yamlTime(t.Resolved))
	fmt.Fprintf(&b, "due: %s\n", yamlTime(t.Due))
	return b.String()
}

func yamlScalar(s string) string {
	if s == "" {
		return `""`
	}
	if strings.ContainsAny(s, "\n\"\t") || needsQuoting(s) {
		return strconv.Quote(s)
	}
	return s
}

func needsQuoting(s string) bool {
	if len(s) == 0 {
		return true
	}
	first := s[0]
	switch first {
	case ' ', '\t', '#', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`', '{', '}', '[', ']', ',', '?', ':', '-':
		return true
	}
	return false
}

func yamlNotes(s string) string {
	if s == "" {
		return `""`
	}
	// Reproduce the style emitted by go-yaml: |2- with a leading blank line for content
	// whose first line is empty, and content lines indented by two spaces. Blank lines
	// within the content are written as a single blank line (no indentation).
	lines := strings.Split(s, "\n")
	var b strings.Builder
	b.WriteString("|2-")
	for _, l := range lines {
		b.WriteString("\n")
		if l != "" {
			b.WriteString("  ")
			b.WriteString(l)
		}
	}
	return b.String()
}

func yamlTime(t time.Time) string {
	if t.IsZero() {
		return "0001-01-01T00:00:00Z"
	}
	return t.UTC().Format(time.RFC3339Nano)
}

// parseTaskYAML parses the limited YAML subset we write ourselves back into a Task.
func parseTaskYAML(data []byte) (*Task, error) {
	t := &Task{}
	lines := strings.Split(string(data), "\n")
	i := 0
	for i < len(lines) {
		line := lines[i]
		if line == "" {
			i++
			continue
		}
		idx := strings.Index(line, ":")
		if idx < 0 {
			i++
			continue
		}
		key := strings.TrimSpace(line[:idx])
		rest := strings.TrimSpace(line[idx+1:])
		switch key {
		case "summary":
			t.Summary = parseYAMLScalar(rest)
		case "notes":
			if strings.HasPrefix(rest, "|") {
				indent := 2
				if m := blockIndent(rest); m > 0 {
					indent = m
				}
				i++
				var sb strings.Builder
				first := true
				for i < len(lines) {
					l := lines[i]
					if l == "" {
						if !first {
							sb.WriteString("\n")
						}
						first = false
						i++
						continue
					}
					if !strings.HasPrefix(l, strings.Repeat(" ", indent)) {
						break
					}
					if !first {
						sb.WriteString("\n")
					}
					sb.WriteString(l[indent:])
					first = false
					i++
				}
				t.Notes = sb.String()
				continue
			}
			t.Notes = parseYAMLScalar(rest)
		case "tags":
			if rest == "[]" {
				t.Tags = nil
				i++
				continue
			}
			i++
			for i < len(lines) && strings.HasPrefix(lines[i], "- ") {
				t.Tags = append(t.Tags, parseYAMLScalar(strings.TrimPrefix(lines[i], "- ")))
				i++
			}
			continue
		case "project":
			t.Project = parseYAMLScalar(rest)
		case "priority":
			t.Priority = rest
		case "delegatedto":
			t.DelegatedTo = parseYAMLScalar(rest)
		case "subtasks", "dependencies":
			i++
			for i < len(lines) && strings.HasPrefix(lines[i], "- ") {
				i++
			}
			continue
		case "created":
			t.Created, _ = time.Parse(time.RFC3339Nano, rest)
		case "resolved":
