package main

import (
	"fmt"
	"sort"
	"strings"
)

const bashCompletion = `# wire bash completions to dstask completion engine. Some of the workarounds for
# idiosyncrasies around separation with colons taken from /etc/bash_completion

_dstask() {
    # reconstruct COMP_WORDS to re-join separations caused by colon (which is a default separator)
    # yes, this method ends up splitting by spaces, but that's not a problem for the dstask parser
    # see http://tiswww.case.edu/php/chet/bash/FAQ
    original_args=( $(echo "${COMP_WORDS[@]}" | sed 's/ : /:/g' | sed 's/ :$/:/g') )

    # hand to dstask as canonical args
    COMPREPLY=( $(dstask _completions "${original_args[@]}") )

    # convert dstask's suggestions to remove prefix before colon so complete can understand it
    local last_arg="${original_args[-1]}"
    local colon_word=${last_arg%"${last_arg##*:}"}
    local i=${#COMPREPLY[*]}
    while [[ $((--i)) -ge 0 ]]; do
        COMPREPLY[$i]=${COMPREPLY[$i]#"$colon_word"}
    done
}

complete -F _dstask dstask
complete -F _dstask task
#complete -F _dstask n
#complete -F _dstask t
`

const zshCompletion = `#compdef dstask
#autoload


_dstask() {
    compadd -- $(dstask _completions "${words[@]}")
}

compdef _dstask dstask
`

const fishCompletion = `#!/usr/bin/env fish

complete -f -c dstask -a (echo (dstask _completions) | string collect)
#complete -f -c task -a (echo (task _completions) | string collect)
#complete -f -c t -a (echo (t _completions) | string collect)

`

// Order matches original binary's completion listing.
var completionCommands = []string{
	"next",
	"add",
	"rm",
	"remove",
	"template",
	"log",
	"start",
	"note",
	"notes",
	"stop",
	"done",
	"resolve",
	"context",
	"modify",
	"edit",
	"undo",
	"sync",
	"open",
	"git",
	"show-next",
	"show-projects",
	"show-tags",
	"show-active",
	"show-paused",
	"show-open",
	"show-resolved",
	"show-templates",
	"show-unorganised",
	"bash-completion",
	"fish-completion",
	"zsh-completion",
	"help",
	"version",
}

var completionCommandSet = func() map[string]bool {
	m := map[string]bool{}
	for _, c := range completionCommands {
		m[c] = true
	}
	return m
}()

func printCompletions(args []string) {
	// `args` is whatever followed the `_completions` command on the command line.
	// The bash helper invokes `dstask _completions "${original_args[@]}"` so the first
	// element is the program name.
	var prior []string
	var prefix string
	switch {
	case len(args) == 0:
		prefix = ""
		prior = nil
	case len(args) == 1:
		// Only the program name was provided: treat as completion at position 0.
		prefix = ""
		prior = nil
	default:
		prefix = args[len(args)-1]
		prior = args[1 : len(args)-1]
	}

	// Determine whether a command has been issued in `prior`.
	usedCommands := map[string]bool{}
	for _, a := range prior {
		if completionCommandSet[a] {
			usedCommands[a] = true
		}
	}

	// If `help` is the first command, subsequent positions take command names too.
	helpContext := false
	for _, a := range prior {
		if a == "help" {
			helpContext = true
			break
		}
	}

	// A prefix that is itself a fully-typed command counts as a used command.
	inFilterMode := len(usedCommands) > 0
	if completionCommandSet[prefix] {
		inFilterMode = true
		usedCommands[prefix] = true
	}

	repo, _ := tryLoadRepoReadOnly()
	var tasks []*Task
	if repo != nil {
		tasks, _ = repo.loadAllTasks()
	}

	tagSet := map[string]bool{}
	projSet := map[string]bool{}
	for _, t := range tasks {
		if t.Status == StatusResolved {
			continue
		}
		for _, tag := range t.Tags {
			tagSet[tag] = true
		}
		if t.Project != "" {
			projSet[t.Project] = true
		}
	}

	// Sorted tag/project slices for stable output.
	var tags []string
	for tag := range tagSet {
		tags = append(tags, tag)
	}
	sort.Strings(tags)
	var projects []string
	for p := range projSet {
		projects = append(projects, p)
	}
	sort.Strings(projects)

	var out []string
	switch {
	case strings.HasPrefix(prefix, "+"):
		for _, tag := range tags {
			out = append(out, "+"+tag)
		}
	case strings.HasPrefix(prefix, "-project:"):
		for _, p := range projects {
			out = append(out, "-project:"+p)
		}
	case strings.HasPrefix(prefix, "-"):
		for _, tag := range tags {
			out = append(out, "-"+tag)
		}
	case strings.HasPrefix(prefix, "project:"):
		for _, p := range projects {
			out = append(out, "project:"+p)
		}
	default:
		if !inFilterMode || helpContext {
			for _, cmd := range completionCommands {
				if usedCommands[cmd] {
